// valuation-tutorials.js — the step-by-step walkthrough for each valuation model in the Company Valuation Studio.
// Ten steps per model, each written at three levels (beginner, intermediate, advanced). Inline markup is limited to
// <b>, <i>, <sub>, <sup> and <code>, which the page renders through a whitelist (no innerHTML). The worked example
// (`worked`) is computed live from the company in the workspace, so the numbers always match the model.
// Sources are ids from valuation-report.js's SOURCES list; the page prints them with authors and dates.
import * as V from '../core/valuation.js?v=30';

const fin = V.fin;
export const LEVELS = [
  { id: 'beginner', name: 'Beginner', blurb: 'Plain words and guided calculations.' },
  { id: 'intermediate', name: 'Intermediate', blurb: 'Statements, forecasting and the complete formulas.' },
  { id: 'advanced', name: 'Advanced', blurb: 'Modelling conventions, sensitivities, capital structure and the assumptions behind the assumptions.' },
];
export const STEPS = [
  ['what', 'What the model does'], ['when', 'When analysts use it'], ['data', 'What information is required'], ['where', 'Where to obtain it'], ['inputs', 'What each input means'],
  ['formulas', 'How every formula works'], ['manual', 'Calculate the result by hand'], ['excel', 'Build the model in Excel'], ['interpret', 'How to interpret the valuation'], ['mistakes', 'Common mistakes and limitations'],
];
const L = (beginner, intermediate, advanced) => ({ beginner, intermediate, advanced });

export const TUTORIALS = {
  // ================================================================ DCF
  dcf: {
    title: 'Discounted cash flow (FCFF at WACC)', sources: ['hbs-dcf', 'hbs-value', 'inv-pitfalls', 'damodaran-book', 'mckinsey'],
    steps: {
      what: L(
        ['A business is worth the cash it will hand to its investors in the future, counted in today’s money. The DCF forecasts that cash year by year, shrinks each year’s amount for the wait and the risk, and adds the pieces up.', 'Cash a long way off is worth less than cash now: you could invest today’s money and have more by then, and the far future is less certain. The <b>discount rate</b> is how much we shrink each year’s cash by.'],
        ['The model forecasts <b>free cash flow to the firm</b> (FCFF): the cash the operations generate after tax and after the investment needed to keep growing, before any payment to lenders or shareholders. Because it belongs to all providers of capital, it is discounted at the blended cost of all capital, the <b>WACC</b>. The present value of the forecast years plus a <b>terminal value</b> for everything after them is the <b>enterprise value</b>. Subtracting debt and other claims and adding cash gives the <b>equity value</b>; dividing by shares gives a value per share.', 'The equity version discounts <b>free cash flow to equity</b> (after interest and borrowing) at the <b>cost of equity</b> instead. Mixing them is the classic error: a cash flow to all capital at an equity rate, or the reverse.'],
        ['FCFF at WACC values the operations independently of how they are financed; the capital structure enters only through the weights and the tax shield in WACC (Modigliani–Miller with taxes). FCFE at k<sub>e</sub> should give the same equity value when leverage is held at the WACC weights; a gap between the two models is a check on the borrowing assumption. The studio runs both.', 'Conventions matter: end-year versus mid-year discounting, whether the terminal value is a growing perpetuity or an exit multiple, and whether leases are debt. The advanced controls expose each one.'],
      ),
      when: L(
        ['Analysts use a DCF when they can forecast a company’s cash with some confidence: an established business with a track record and a plan. It is the most common method for valuing whole companies and the one taught first in corporate finance.'],
        ['DCF is the workhorse for mature and growth companies with positive or forecastable cash flows: mergers, fairness opinions, equity research targets, impairment tests. It is weak where cash flows cannot be defined (banks, insurers), where they are negative for years (start-ups, so the whole value sits in a distant terminal value), and where assets rather than earnings carry the value (property, holding companies).'],
        ['Use DCF alongside multiples, never instead of them: the DCF makes the assumptions explicit and the multiples show what the market will actually pay. For banks, use dividend or excess-return models; for cyclical companies, normalise mid-cycle cash flows; for start-ups, pair a long-horizon DCF with the venture-capital method and read the result as a scenario, not a point.'],
      ),
      data: L(
        ['The latest year’s revenue, operating profit, depreciation, capital spending and working capital; the company’s debt and cash; the number of shares; and a share price if it is listed. Three to five years of history help you see the trend.'],
        ['Income statement: revenue, cost of goods sold, operating expenses, D&A, EBIT, interest, tax. Balance sheet: cash, receivables, inventory, payables, debt, equity. Cash flow statement: operating cash flow and capital expenditure. Market data: share price, diluted shares, beta, the risk-free rate, the equity risk premium and the cost of debt. The studio marks what each model needs and what is optional.'],
        ['Add anything that changes the bridge from enterprise to equity value: lease liabilities (IFRS 16 puts them on the balance sheet), pension deficits, minority interests, preferred stock, non-operating assets, options and convertibles for the diluted share count. For the forecast you want segment disclosures, capacity, pricing, the capex plan and the working-capital cycle.'],
      ),
      where: L(
        ['Listed companies publish annual reports with all three statements; in the United States they are filed with the SEC on EDGAR as Form 10-K, free to read. Share prices are on any finance site. For a private company, ask for its audited accounts.'],
        ['SEC EDGAR (sec.gov) holds every 10-K and 10-Q and exposes the XBRL figures through its API, which the studio can map automatically or from an uploaded JSON. Investor-relations pages hold presentations and guidance. Beta can be estimated from price history (the Stock analysis page does this) or taken from a data provider; the equity risk premium and country spreads are published by Damodaran each January.'],
        ['Prefer the filing to the data provider when they disagree. Reconcile the cash-flow statement to the balance sheet (the studio checks that the three cash flows explain the change in cash). Read the notes for leases, pensions, share-based pay, contingent liabilities and segment data. Use market values for debt where bonds trade; book values are a fallback.'],
      ),
      inputs: L(
        ['<b>Revenue growth</b>: how fast sales grow each year. <b>EBITDA margin</b>: operating profit before depreciation as a share of sales. <b>Capex</b>: money spent on equipment and buildings. <b>Working capital</b>: money tied up in stock and unpaid invoices. <b>Tax rate</b>: the share of operating profit paid as tax. <b>WACC</b>: the discount rate. <b>Terminal growth</b>: how fast cash grows after the forecast, forever.'],
        ['Each driver is a percentage of revenue by year, so the forecast scales: D&A, capex and working capital as % of revenue, EBITDA (or EBIT) margin, and a tax rate applied to EBIT. The WACC is built from CAPM (risk-free rate, beta, equity risk premium) for equity and an after-tax cost of debt, weighted by market values. Terminal value is either a perpetuity at growth g or an exit multiple of final-year EBITDA. The bridge takes debt, leases if chosen, preferred, minority interest and other claims off, and adds cash and non-operating assets.'],
        ['Advanced inputs: a target capital structure for the weights (relevered beta if you change it), mid-year discounting, whether losses create tax credits, the debt-funding share in the FCFE model, and the terminal-year reinvestment. In steady state, capex should exceed D&A by roughly g ÷ return on new capital times NOPAT; a terminal year with capex below depreciation while growing is internally inconsistent.'],
      ),
      formulas: L(
        ['Each year’s cash is divided by (1 + rate) once for every year of waiting. The last year’s cash is turned into a value for all later years with the perpetuity formula: next year’s cash ÷ (rate − growth).'],
        ['FCFF = EBIT × (1 − t) + D&A − capex − ΔNWC. PV = Σ FCFF<sub>t</sub> ÷ (1 + WACC)<sup>t</sup>. Terminal value = FCFF<sub>N</sub> × (1 + g) ÷ (WACC − g), discounted by (1 + WACC)<sup>N</sup>. WACC = E/V × k<sub>e</sub> + D/V × k<sub>d</sub> × (1 − t) with k<sub>e</sub> = r<sub>f</sub> + β × ERP. Equity = EV − net debt − other claims.'],
        ['Mid-year: exponent t − ½ for the flows and N − ½ for a perpetuity terminal value (an exit multiple stays at N, since multiples are struck at year end). Implied exit multiple = TV ÷ EBITDA<sub>N</sub>; implied growth from an exit multiple = (TV × WACC − FCFF<sub>N</sub>) ÷ (TV + FCFF<sub>N</sub>). Each is a cross-check on the other.'],
      ),
      excel: L(
        ['Put the assumptions in one column of blue cells (growth, margin, capex %, tax, WACC, terminal growth). Lay the years across the top. Each row below is a formula that uses the row above and the assumptions. The studio’s Excel export does exactly this, so open it and follow the formulas.'],
        ['Sheet 1, Inputs: one input per row, blue on yellow. Sheet 2, Forecast: row 11 revenue <code>=prior*(1+growth)</code>, row 12 EBITDA <code>=revenue*margin</code>, D&A, EBIT, tax <code>=MAX(0,EBIT)*rate</code>, NOPAT, capex, NWC, ΔNWC, FCFF; then discount factor <code>=1/(1+WACC)^t</code>, PV, SUM, terminal value <code>=FCFF_N*(1+g)/(WACC-g)</code>, EV, bridge, per share. Never type a number into a formula row.'],
        ['Add a switch cell for perpetuity versus exit multiple and one for mid-year (<code>=t-0.5*switch</code>). Build the WACC on its own block with relevered beta. Add a data table (What-if analysis → Data table) with WACC down the side and g across for the sensitivity grid. Check cells: EV − PVs − PV(TV) = 0; implied multiple against peers; capex ≥ D&A in the terminal year.'],
      ),
      interpret: L(
        ['The number is a point inside a range. Look at how much of the value comes from the terminal value: if most of it does, the answer depends on guesses about the distant future. Compare the value per share with the market price and ask which assumptions the market seems to be making.'],
        ['Read the three things together: the per-share value against the price, the share of value in the terminal period, and the sensitivity grid. Then ask what the exit multiple implied by your perpetuity assumption looks like against peers. A DCF that implies 20× EBITDA for a company whose peers trade at 9× is telling you the growth or margin assumptions are generous.'],
        ['Reverse the model: find the terminal growth or WACC at which value equals price (the studio reports both) and judge whether the market’s implied assumptions are more or less plausible than yours. Decompose the gap between your value and the price into growth, margin and discount-rate components with the sensitivity tables. Report a range from scenarios, not a point.'],
      ),
      mistakes: L(
        ['Growing cash forever faster than the economy; forgetting debt when going from company value to share value; using a discount rate that is too low; and trusting a single number without looking at how much it moves when assumptions change a little.'],
        ['Mixing FCFF with the cost of equity (or FCFE with WACC); double-counting interest; forgetting ΔNWC; capex below D&A in a growing terminal year; terminal growth above long-run nominal GDP; using book weights in WACC; counting cash twice (in EV weights and the bridge); ignoring dilution from options; and treating the 5-year forecast as precise when the uncertainty grows every year.'],
        ['Adding an arbitrary risk premium to WACC for risks already in the cash flows (the register here changes cash flows instead); applying a small-company or illiquidity discount without evidence; inconsistent inflation (nominal rates with real cash flows); terminal value struck off an unnormalised final year; ignoring the tax shield lost when losses cannot be used; and believing the model more because the spreadsheet is bigger.'],
      ),
    },
    worked(ctx, f) {
      const d = ctx.results?.dcf; if (!d?.ok) return [];
      const r0 = d.rows[0], last = d.rows[d.N - 1];
      return [
        `Start from ${ctx.project.meta?.name || 'the company'}’s latest revenue of ${f.money(d.forecast.base.revenue)}. Year 1 revenue = ${f.money(d.forecast.base.revenue)} × (1 + ${f.pct(r0.growth)}) = <b>${f.money(r0.revenue)}</b>.`,
        `EBITDA = revenue × margin = ${f.money(r0.revenue)} × ${f.pct(r0.margin)} = <b>${f.money(r0.ebitda)}</b>; less D&A of ${f.money(r0.da)} gives EBIT <b>${f.money(r0.ebit)}</b>.`,
        `Tax on EBIT at ${f.pct(r0.taxRate)} = ${f.money(r0.tax)}, so NOPAT = <b>${f.money(r0.nopat)}</b>.`,
        `FCFF = NOPAT + D&A − capex − ΔNWC = ${f.money(r0.nopat)} + ${f.money(r0.da)} − ${f.money(r0.capex)} − ${f.money(r0.dNwc)} = <b>${f.money(r0.fcff)}</b>.`,
        `WACC: cost of equity = ${f.pct(ctx.A.discount.rf)} + ${f.num(ctx.A.discount.beta, 2)} × ${f.pct(ctx.A.discount.erp)} = ${f.pct(d.cc.ke, 2)}; after-tax cost of debt = ${f.pct(ctx.A.discount.kd)} × (1 − ${f.pct(ctx.A.discount.taxRate, 0)}) = ${f.pct(d.cc.kdAfter, 2)}; weights ${f.pct(d.cc.we, 0)} : ${f.pct(d.cc.wd, 0)} give <b>${f.pct(d.r, 2)}</b>.`,
        `Discount year 1: ${f.money(r0.fcff)} ÷ (1 + ${f.pct(d.r, 2)})<sup>${f.num(r0.exponent, 1)}</sup> = ${f.money(r0.fcff)} × ${f.num(r0.df, 4)} = <b>${f.money(r0.pv)}</b>. Repeat for every year; the ${d.N} present values sum to <b>${f.money(d.sumPv)}</b>.`,
        d.assumptions.terminal.method === 'exit'
          ? `Terminal value = year-${d.N} EBITDA ${f.money(last.ebitda)} × ${f.x(d.assumptions.terminal.multiple)} = <b>${f.money(d.tv)}</b>; discounted ${d.N} years: <b>${f.money(d.pvTV)}</b>.`
          : `Terminal value = FCFF<sub>${d.N}</sub> × (1 + g) ÷ (WACC − g) = ${f.money(last.fcff)} × ${f.num(1 + d.assumptions.terminal.growth, 3)} ÷ (${f.pct(d.r, 2)} − ${f.pct(d.assumptions.terminal.growth)}) = <b>${f.money(d.tv)}</b>; discounted: <b>${f.money(d.pvTV)}</b> (${f.pct(d.tvShare, 0)} of EV).`,
        `Enterprise value = ${f.money(d.sumPv)} + ${f.money(d.pvTV)} = <b>${f.money(d.ev)}</b>. Equity = EV − debt ${f.money(d.debt)}${d.leases ? ` − leases ${f.money(d.leases)}` : ''} − preferred and minority ${f.money(d.preferred + d.minority)} + cash ${f.money(d.cash)} = <b>${f.money(d.equity)}</b>${fin(d.perShare) ? `, or <b>${f.perShare(d.perShare)}</b> a share over ${f.num(d.shares, 1)} ${f.unitLabel} shares` : ''}.`,
      ];
    },
  },
  // ================================================================ comparables
  comps: {
    title: 'Comparable company analysis', sources: ['inv-valuation', 'hbs-value', 'cfa', 'damodaran-book'],
    steps: {
      what: L(['Look at what the market pays for similar companies, as a multiple of their profits or sales, and apply the same multiple to this company.'], ['Relative valuation: each peer’s enterprise value or market capitalisation divided by a metric (EBITDA, EBIT, revenue, earnings, book equity, free cash flow) gives a multiple; the peer median or range, times the target’s own metric, gives its implied value. EV multiples give enterprise value (then the bridge to equity); equity multiples give equity directly.'], ['Multiples are shorthand for a DCF: EV/EBITDA rises with growth and return on capital and falls with risk and reinvestment needs. Two companies with the same EBITDA deserve different multiples if their growth or margins differ, which is why peer selection and adjustment matter more than the arithmetic.']),
      when: L(['Whenever there are listed companies like this one. Analysts always run it next to a DCF because it shows what buyers actually pay today.'], ['For a cross-check on intrinsic value, for a quick valuation when a forecast is not possible, for IPO pricing and for M&A (with precedent-transaction multiples, which include a control premium). Less useful when the company has no close peers, when peers are at different points in a cycle, or when the market as a whole is mispriced.'], ['Use forward multiples (next-year EBITDA) where estimates exist; they strip out one-off years. For loss-makers use EV/Revenue or sector multiples (EV/subscriber, price per bed); for banks P/B and P/E against ROE; for property, price to NAV.']),
      data: L(['For each peer: share price, number of shares, debt, cash, revenue, EBITDA, EBIT, net income, book equity and free cash flow. The same lines for this company.'], ['Market capitalisation and enterprise value for each peer (price × diluted shares + debt + preferred + minority − cash), and the denominators for the last twelve months or the next year. The target’s own metrics on the same basis and period.'], ['Normalise: remove one-offs, align fiscal year ends, treat leases consistently (IFRS 16 raises EBITDA and debt), convert currencies at the same date, and check whether peers capitalise or expense development costs.']),
      where: L(['Finance websites list prices, market caps and the main ratios; annual reports have the rest. Pick five to ten peers in the same industry and of similar size.'], ['Company filings for the fundamentals; exchange data for prices and share counts; the company’s own 10-K often names its competitors; industry classification codes (SIC, GICS) help build the long list before you shorten it on size, growth, margins and geography.'], ['Document each peer’s inclusion with the reason and the date of the price. A good peer set is defensible on fundamentals (growth, margin, capital intensity, risk) rather than just on the industry label; consider peers from adjacent sectors with the same economics.']),
      inputs: L(['The <b>multiple</b> is the price divided by a measure of size or profit. <b>Median</b> is the middle value of the peers; <b>25th and 75th percentiles</b> give a range. The studio applies the range to this company’s own figures.'], ['P/E = market cap ÷ net income; EV/EBITDA, EV/EBIT, EV/Revenue = enterprise value ÷ the metric; P/B = market cap ÷ book equity; P/FCF = market cap ÷ free cash flow. Negative or zero denominators make the multiple meaningless (n/m) and the peer is dropped from that multiple.'], ['Choose the statistic: the median resists outliers; the mean does not; the interquartile range is the usual band. Weight peers by closeness if you must, but say so. Apply the multiple to the target’s normalised metric, not the reported one.']),
      formulas: L(['Implied value = peer multiple × this company’s own number.'], ['Implied EV = median EV/EBITDA × target EBITDA; implied equity = implied EV − net debt − minority − preferred; per share = ÷ diluted shares. For P/E: implied equity = median P/E × target net income.'], ['Percentiles use linear interpolation between order statistics (NumPy’s default; the studio matches it). Own multiple = target EV ÷ target metric at the current price: the premium or discount to peers is own ÷ median − 1.']),
      excel: L(['One row per peer with price, shares, debt, cash and the profit lines; columns that compute market cap, EV and each multiple; then <code>MEDIAN</code>, <code>QUARTILE</code> and a block that multiplies them by this company’s numbers.'], ['Columns: market cap <code>=price*shares</code>, EV <code>=mcap+debt-cash</code>, EV/EBITDA <code>=IF(ebitda>0,EV/ebitda,"n/m")</code>; stats with <code>=MEDIAN(range)</code>, <code>=QUARTILE.INC(range,1)</code>, <code>=QUARTILE.INC(range,3)</code>; implied EV = stat × target EBITDA; equity bridge; per share.'], ['Add a football-field chart (stacked bar with the low as an invisible series). Keep a peer-selection sheet with the reasons. Use <code>AGGREGATE</code> or filter to skip "n/m" text in statistics.']),
      interpret: L(['If the implied value is far from the DCF, one of the two is making different assumptions about growth or risk. A company trading below its peers is not automatically a bargain: it may deserve a lower multiple because it grows more slowly or earns less.'], ['Explain any discount or premium with fundamentals: compare the target’s margin and growth with the peers’. A low multiple with a low margin is fair; a low multiple with peer-level margins and growth is worth investigating (or the market knows something: leverage, governance, a pending lawsuit).'], ['Regress peer multiples on growth and margin to see where the target should sit; the residual is the unexplained premium. Reconcile with the DCF: the implied exit multiple from your perpetuity should be near the peer median, or your terminal assumptions differ from the market’s.']),
      mistakes: L(['Comparing with companies that are not really similar; mixing up company value (EV) with share value (market cap); and taking a low multiple as proof of a cheap share.'], ['EV multiples applied to equity metrics or the reverse; mismatched periods; including one-off gains; too few peers; ignoring leverage differences in P/E; averaging in a peer with a bubble multiple; forgetting dilution.'], ['Circularity when the peers themselves are mispriced; sector-wide bubbles; control premia in transaction multiples applied to minority stakes; multiples at different dates; and reporting a point estimate when the peer range itself spans ±30%.']),
    },
    worked(ctx, f) {
      const c = ctx.results?.comps; if (!c?.ok) return [];
      const ev = c.table.find((t) => t.id === 'evEbitda'); if (!ev) return [];
      const pe0 = c.peers[0];
      return [
        `Take the first peer, ${pe0.name}: market cap = ${f.perShare(pe0.price)} × ${f.num(pe0.shares, 1)} = ${f.money(pe0.marketCap)}; EV = market cap + debt − cash = ${f.money(pe0.marketCap)} + ${f.money(pe0.debt)} − ${f.money(pe0.cash)} = <b>${f.money(pe0.ev)}</b>.`,
        `Its EV/EBITDA = ${f.money(pe0.ev)} ÷ ${f.money(pe0.ebitda)} = <b>${ev.values[0] === null ? 'n/m' : f.x(ev.values[0])}</b>. Across the ${ev.stats.n} usable peers the multiples run from ${f.x(ev.stats.min)} to ${f.x(ev.stats.max)}; median <b>${f.x(ev.stats.median)}</b>, 25th–75th percentiles ${f.x(ev.stats.q1)}–${f.x(ev.stats.q3)}.`,
        `Implied EV for ${ctx.project.meta?.name || 'the company'} = ${f.x(ev.stats.median)} × its EBITDA ${f.money(ev.targetMetric)} = <b>${f.money(ev.implied.median.value)}</b>; less net debt and other claims gives equity <b>${f.money(ev.implied.median.equity)}</b>${fin(ev.implied.median.perShare) ? `, or <b>${f.perShare(ev.implied.median.perShare)}</b> a share` : ''}.`,
        fin(ev.own) ? `At the current price the company trades at ${f.x(ev.own)}, a ${ev.own < ev.stats.median ? 'discount' : 'premium'} of ${f.pct(Math.abs(ev.own / ev.stats.median - 1), 0)} to the peer median. Before calling that cheap or dear, compare its margin and growth with the peers’.` : 'Enter a share price to see where the company trades against its peers.',
      ];
    },
  },
  // ================================================================ DDM
  ddm: {
    title: 'Dividend discount models', sources: ['gordon', 'hbs-dcf', 'cfa', 'damodaran-book'],
    steps: {
      what: L(['A share is worth the dividends it will pay, counted in today’s money. If dividends grow steadily forever, one formula gives the value: next year’s dividend divided by (required return − growth).'], ['The Gordon growth model values a share as D<sub>1</sub> ÷ (k<sub>e</sub> − g). A multi-stage model forecasts dividends explicitly for some years (growing faster or slower) and then applies Gordon to the dividend after the last explicit year. Because dividends go to shareholders only, the discount rate is the cost of equity.'], ['DDM is the FCFE model with dividends standing in for the cash available to equity. It is exact when the company pays out what it could; when payout is below capacity it understates value (the retained cash is ignored), and when payout exceeds capacity it overstates it. The H-model and three-stage variants smooth the transition from high to stable growth.']),
      when: L(['For companies that pay steady, predictable dividends: utilities, banks, mature consumer companies.'], ['Appropriate where dividends track earning power and the payout policy is stable; the standard approach for banks and insurers, where free cash flow to the firm is undefined. Not usable for companies that pay no dividend, and unreliable for young payers whose dividends will change as they mature.'], ['For non-payers substitute potential dividends (FCFE) or total payout including buybacks. Where buybacks are large, a dividends-only DDM understates value; use dividends + net buybacks per share.']),
      data: L(['The latest dividend per share, a growth rate and the return shareholders require.'], ['Dividends paid (total or per share) for several years, shares outstanding, the cost of equity (CAPM), a growth rate for the explicit stage and a terminal growth rate below the cost of equity; the payout ratio and return on equity to check that growth is sustainable (g ≈ retention × ROE).'], ['History of dividends and buybacks, earnings, ROE and the payout policy from the annual report; analyst dividend forecasts for the explicit stage; the sustainable growth rate as a ceiling on terminal growth.']),
      where: L(['Dividends are in the cash-flow statement and the annual report; the dividend per share is on any finance site.'], ['Cash-flow statement (dividends paid), the equity statement, and the investor-relations dividend history. Cost of equity from CAPM with beta from price history and the equity risk premium from Damodaran’s annual data.'], ['Check declared versus paid dividends (timing), special dividends (exclude), and dividends on preferred shares (deduct first).']),
      inputs: L(['<b>D<sub>0</sub></b> is the dividend just paid; <b>g</b> is the growth rate; <b>k<sub>e</sub></b> is the return shareholders require.'], ['D<sub>1</sub> = D<sub>0</sub> × (1 + g). Stage-one growth and its length; terminal growth; cost of equity. The studio takes the dividend per share from dividends paid ÷ shares outstanding, or a figure you enter.'], ['Growth must be consistent with payout and ROE: g = (1 − payout) × ROE. Terminal growth must be below the cost of equity and no higher than long-run nominal growth. A stage-one growth above k<sub>e</sub> is fine for a limited period.']),
      formulas: L(['Value = next year’s dividend ÷ (required return − growth).'], ['P<sub>0</sub> = D<sub>1</sub> ÷ (k<sub>e</sub> − g). Multi-stage: P<sub>0</sub> = Σ D<sub>t</sub> ÷ (1 + k<sub>e</sub>)<sup>t</sup> + [D<sub>N</sub> × (1 + g) ÷ (k<sub>e</sub> − g)] ÷ (1 + k<sub>e</sub>)<sup>N</sup>.'], ['Implied cost of equity = D<sub>1</sub> ÷ P + g (the dividend yield plus growth), a useful reverse check. The present value of growth opportunities = P<sub>0</sub> − EPS ÷ k<sub>e</sub>.']),
      excel: L(['A column of years, the dividend growing each year, a discount factor, and the sum; plus the terminal value formula at the end.'], ['Rows: year, growth, dividend <code>=prior*(1+g)</code>, factor <code>=1/(1+ke)^t</code>, PV; terminal <code>=D_N*(1+gT)/(ke-gT)</code> discounted at N; total <code>=SUM(PV)+PV(TV)</code>.'], ['Add a switch for including buybacks per share; a check that g<sub>T</sub> < k<sub>e</sub>; and a data table of value against k<sub>e</sub> and g<sub>T</sub>.']),
      interpret: L(['If most of the value comes from the terminal formula, the answer rests on two small numbers (required return and growth) and moves a lot when they change.'], ['Compare the DDM value with the DCF: a DDM well below the DCF usually means payout is below capacity (retained cash is creating value the DDM does not see). Compare the implied cost of equity with CAPM.'], ['Decompose into the value of current dividends and the present value of growth; test the sustainability of growth against ROE and payout; and read the sensitivity to the spread k<sub>e</sub> − g.']),
      mistakes: L(['Using the dividend just paid instead of next year’s; letting growth be as high as the required return (the formula explodes); applying it to a company that pays nothing.'], ['Growth above the sustainable rate; terminal growth above nominal GDP; ignoring buybacks; using WACC instead of the cost of equity; forgetting preferred dividends.'], ['Treating a temporarily high payout as permanent; applying a single-stage model to a company in transition; assuming the dividend policy is independent of leverage and investment; and mistaking a high yield for safety when it signals an expected cut.']),
    },
    worked(ctx, f) {
      const d = ctx.results?.ddm; if (!d?.ok) return [];
      const g = d.gordon, m = d.multi;
      return [
        `Dividend per share just paid: D<sub>0</sub> = <b>${f.perShare(d.dps)}</b>${fin(d.payout) ? ` (payout ${f.pct(d.payout, 0)} of earnings)` : ''}. Cost of equity k<sub>e</sub> = <b>${f.pct(d.ke, 2)}</b>.`,
        g.ok ? `Gordon: D<sub>1</sub> = ${f.perShare(d.dps)} × (1 + ${f.pct(ctx.project.ddm?.gT ?? 0.025)}) = ${f.perShare(g.d1)}; value = ${f.perShare(g.d1)} ÷ (${f.pct(d.ke, 2)} − ${f.pct(ctx.project.ddm?.gT ?? 0.025)}) = <b>${f.perShare(g.value)}</b>.` : `Gordon: ${g.error}`,
        m.ok ? `Multi-stage: dividends grow at ${f.pct(ctx.project.ddm?.g1 ?? 0.05)} for ${m.N} years (year ${m.N} dividend ${f.perShare(m.rows[m.N - 1].dividend)}); their present values sum to ${f.perShare(m.sumPv)}. Terminal value at year ${m.N} = ${f.perShare(m.rows[m.N - 1].dividend)} × (1 + g) ÷ (k<sub>e</sub> − g) = ${f.perShare(m.tv)}, discounted to ${f.perShare(m.pvTV)}. Total <b>${f.perShare(m.value)}</b> (${f.pct(m.tvShare, 0)} from the terminal stage).` : `Multi-stage: ${m.error}`,
      ];
    },
  },
  // ================================================================ asset-based
  asset: {
    title: 'Asset-based valuation', sources: ['hbs-value', 'inv-valuation', 'fasb-350', 'cfa'],
    steps: {
      what: L(['Add up what the company owns, take away what it owes. The balance sheet gives one answer (book value); adjusting each asset to what it would really fetch gives another.'], ['Book value is shareholders’ equity as reported. Tangible book value removes goodwill and intangibles. Adjusted net asset value restates each asset at an estimate of market value. Liquidation value applies recovery rates and deducts selling costs: what shareholders would get if the business stopped.'], ['Accounting value is historical cost less depreciation, under conservatism: it understates assets that appreciate (land, brands built in-house, which are never on the sheet) and can overstate those that have lost value until an impairment is booked (ASC 350 for goodwill). Economic value is what the assets can earn or fetch, which is why asset-based values are floors for going concerns and ceilings for failing ones.']),
      when: L(['For companies whose value is mostly in things they own: property companies, holding companies, investment funds, and businesses that are being wound up.'], ['Standard for real-estate companies (NAV), holding companies, asset-heavy businesses in decline, and in distress and insolvency analysis, where liquidation value sets the floor for creditors and the ceiling for what shareholders can expect. A sanity check for any valuation.'], ['Also used in a sum-of-the-parts for investment holdings, in fairness opinions as a floor, and in bank valuation via adjusted book value. It is unhelpful where value lies in people, brands, code and contracts that the balance sheet does not carry.']),
      data: L(['The balance sheet: each kind of asset, total liabilities and equity.'], ['Every balance-sheet line (cash, receivables, inventory, PP&E, goodwill, intangibles, other assets; all liabilities, minority interests, preferred); the notes with fair values of property and investments; and estimates of what each asset class would recover in a sale.'], ['Independent appraisals for property; market prices for securities; inventory ageing; receivables ageing; off-balance-sheet commitments and contingent liabilities; the costs of liquidation (fees, severance, lease breaks).']),
      where: L(['The annual report’s balance sheet and the notes behind it.'], ['Filings for book values; property valuations and investment fair values are in the notes (IFRS 13 fair-value hierarchy); recovery rates from restructuring experience: receivables 60–90%, inventory 30–70%, equipment 20–60%, intangibles near zero.'], ['Court filings and liquidation analyses in bankruptcy cases are public and give realised recovery rates by asset class; auction results for equipment; for real estate, cap rates by market.']),
      inputs: L(['Book values from the balance sheet; an adjustment for each asset (how much more or less it is worth); recovery rates for a sale.'], ['Adjustments as percentages (+20% on PP&E, −10% on inventory); recovery rates for an orderly sale (time to find buyers) and a forced sale (quick disposal); selling costs as a percentage of proceeds; liabilities at face value.'], ['Deferred-tax effects of revaluations; liabilities that crystallise on liquidation (severance, lease terminations, environmental); priority of claims; and the treatment of goodwill (zero in liquidation, but it may represent real acquired brands that could be sold).']),
      formulas: L(['Book value = assets − liabilities. Liquidation value = what the assets fetch − costs − liabilities.'], ['Tangible book = equity − goodwill − intangibles. Adjusted NAV = Σ assets × (1 + adjustment) − liabilities × (1 + adjustment) − minority − preferred. Liquidation = Σ assets × recovery − costs × gross proceeds − liabilities − claims.'], ['Per share = ÷ diluted shares. Price-to-book and price-to-NAV compare the market’s view with the accounting one; a persistent discount to NAV signals expected value destruction or costs the NAV ignores.']),
      excel: L(['One row per asset with the book value and a recovery percentage; multiply; sum; subtract liabilities.'], ['Columns: book, adjustment %, adjusted, orderly rate, orderly proceeds, forced rate, forced proceeds; totals; selling costs <code>=gross*cost%</code>; net <code>=gross-costs-liabilities</code>; per share.'], ['Use scenarios for recovery rates (data table), add a waterfall of claims by priority, and a reconciliation to reported equity.']),
      interpret: L(['A going concern should be worth more than its assets; if the shares trade below liquidation value, either the business is destroying value or the asset figures are wrong.'], ['Compare DCF and asset values: the gap is the value of the franchise (people, brands, position). A DCF below tangible book says the company earns less than its cost of capital on its assets. Liquidation value is the shareholders’ floor; subtract a margin for the time and uncertainty of realising it.'], ['Use the asset value as a floor in the football field and in distress analysis; read P/B against ROE (P/B = (ROE − g) ÷ (k<sub>e</sub> − g) for a stable firm) to see whether the discount or premium is justified.']),
      mistakes: L(['Treating book value as what the company is worth; forgetting that goodwill cannot be sold; ignoring the costs of selling.'], ['Revaluing assets but not liabilities; ignoring tax on gains; using optimistic recovery rates; forgetting off-balance-sheet obligations; mixing up equity attributable to the parent with total equity.'], ['Applying liquidation logic to a healthy company (or going-concern logic to a failing one); double-counting intangibles that a DCF already values; and ignoring the order of claims when equity is thin.']),
    },
    worked(ctx, f) {
      const a = ctx.results?.asset; if (!a?.ok) return [];
      const top = a.orderly.rows.slice().sort((x, y) => y.book - x.book)[0];
      return [
        `Book value = shareholders’ equity = <b>${f.money(a.book)}</b>${fin(a.perShare.book) ? ` (${f.perShare(a.perShare.book)} a share)` : ''}. Tangible book value strips goodwill and intangibles: <b>${f.money(a.tangible)}</b>.`,
        `Orderly liquidation: apply a recovery rate to each asset, for example ${top.label.toLowerCase()} ${f.money(top.book)} × ${f.pct(top.rate, 0)} = ${f.money(top.proceeds)}. Gross proceeds across all assets: ${f.money(a.orderly.gross)}; less selling costs ${f.pct(a.costs, 0)} (${f.money(a.orderly.cost)}) and liabilities and other claims ${f.money(a.liabilities + a.claims)} = <b>${f.money(a.orderly.net)}</b>${fin(a.orderly.perShare) ? ` (${f.perShare(a.orderly.perShare)} a share)` : ''}.`,
        `A forced sale recovers less: <b>${f.money(a.forced.net)}</b>. The adjusted net asset value with your adjustments is <b>${f.money(a.adjustedNav)}</b>.`,
      ];
    },
  },
  // ================================================================ FCFE
  fcfe: {
    title: 'Free cash flow to equity', sources: ['hbs-dcf', 'damodaran-book', 'cfa'],
    steps: {
      what: L(['The same idea as the DCF, but counting only the cash left for shareholders after lenders are paid and new borrowing comes in, and shrinking it at the return shareholders require.'], ['FCFE = net income + D&A − capex − ΔNWC + net borrowing. It is discounted at the cost of equity to give equity value directly, with no bridge. Net borrowing is the debt raised less repaid; the studio assumes debt funds a fixed share of net investment, so leverage stays roughly constant.'], ['FCFE at k<sub>e</sub> and FCFF at WACC agree when the debt ratio used for net borrowing equals the WACC weight and k<sub>e</sub> is consistent with that leverage (relevered beta). The model is more sensitive than FCFF because leverage magnifies both the cash flows and the discount rate; use it when the capital structure is changing or when debt is hard to value.']),
      when: L(['When you want the value of the shares directly, or when the company’s borrowing is changing a lot.'], ['For financial firms (with FCFE defined through regulatory capital rather than capex), leveraged buyouts and recapitalisations where leverage changes by plan, and as a check on the FCFF model.'], ['Prefer FCFE where debt has no reliable market value, where interest and principal schedules are known, or where the equity holders’ cash matters (a dividend-capacity analysis).']),
      data: L(['Everything the DCF needs, plus the interest cost of the debt and how much new borrowing is planned.'], ['Net income path (EBIT less interest, taxed), D&A, capex, ΔNWC, interest rate on debt, the opening debt balance and the net-borrowing policy (a share of net investment, or an explicit schedule).'], ['Debt schedule with maturities and rates; covenants; planned buybacks and issues; the relevered cost of equity for the target leverage.']),
      where: L(['The same statements as the DCF; the debt notes give interest rates and repayments.'], ['Debt footnotes for rates and maturities; the cash-flow statement for issues and repayments; management’s stated leverage target.'], ['Credit ratings and spreads for the marginal cost of debt; bond prices for market values.']),
      inputs: L(['<b>Net borrowing</b>: new debt minus repayments. <b>Cost of equity</b>: the return shareholders need, from CAPM.'], ['Debt-funding share: the fraction of (capex − D&A + ΔNWC) financed with debt (default: the debt weight in WACC). Pre-tax cost of debt for interest. Cost of equity k<sub>e</sub> = r<sub>f</sub> + β × ERP. Terminal growth and horizon as in the DCF.'], ['Beta should reflect the leverage assumed: β<sub>L</sub> = β<sub>U</sub> × [1 + (1 − t) × D/E]. A changing debt ratio needs a changing k<sub>e</sub> year by year, which the studio approximates with a constant one.']),
      formulas: L(['Cash to shareholders each year, discounted at their required return, plus a terminal value.'], ['FCFE<sub>t</sub> = NI<sub>t</sub> + D&A<sub>t</sub> − capex<sub>t</sub> − ΔNWC<sub>t</sub> + NB<sub>t</sub>, with NI = (EBIT − k<sub>d</sub> × D<sub>t−1</sub>) × (1 − t) and NB = δ × (capex − D&A + ΔNWC). Equity = Σ FCFE<sub>t</sub> ÷ (1 + k<sub>e</sub>)<sup>t</sup> + [FCFE<sub>N</sub> × (1 + g) ÷ (k<sub>e</sub> − g)] ÷ (1 + k<sub>e</sub>)<sup>N</sup>.'], ['Equivalence check: FCFE = FCFF − interest × (1 − t) + net borrowing. Discounting FCFE at WACC or FCFF at k<sub>e</sub> is the mismatch to avoid.']),
      excel: L(['Add rows for interest, net income and net borrowing under the DCF rows, then discount at the cost of equity instead of WACC.'], ['Rows: opening debt, interest <code>=kd*opening debt</code>, net income <code>=(EBIT-interest)*(1-t)</code>, net borrowing <code>=share*(capex-DA+dNWC)</code>, closing debt, FCFE, factor <code>=1/(1+ke)^t</code>, PV, terminal, equity, per share.'], ['Make k<sub>e</sub> a function of the year’s D/E via relevered beta for a changing structure; reconcile to the FCFF model in a check row.']),
      interpret: L(['Compare with the DCF value per share. If they differ a lot, the borrowing assumption is doing the work.'], ['A higher FCFE value than FCFF usually means the model borrows more than the WACC weights imply (debt-funded payouts); a lower one means it de-leverages. Neither is wrong, but it must be a deliberate policy.'], ['Use FCFE to test dividend capacity: FCFE − dividends − buybacks = cash building up or being drawn down. Persistent negative FCFE means equity issues or rising leverage.']),
      mistakes: L(['Forgetting that new borrowing is cash to shareholders only until it has to be repaid; using the company-wide discount rate instead of the shareholders’.'], ['Discounting FCFE at WACC; ignoring that interest changes with debt; a debt-funding share that quietly re-levers the company; negative FCFE in the terminal year.'], ['Holding beta fixed while leverage changes; double-counting cash (interest income in net income and cash in a bridge); and treating FCFE as sustainable when it is funded by borrowing beyond capacity.']),
    },
    worked(ctx, f) {
      const r = ctx.results?.fcfe; if (!r?.ok) return [];
      const y = r.rows[0];
      return [
        `Year 1: interest = ${f.pct(ctx.A.discount.kd)} × opening debt ${f.money(ctx.results.dcf?.debt ?? NaN)} = ${f.money(y.interest)}; net income = (EBIT ${f.money(y.ebit)} − interest) × (1 − ${f.pct(y.taxRate, 0)}) = <b>${f.money(y.netIncome)}</b>.`,
        `Net borrowing = ${f.pct(r.debtFunding, 0)} × (capex ${f.money(y.capex)} − D&A ${f.money(y.da)} + ΔNWC ${f.money(y.dNwc)}) = ${f.money(y.netBorrowing)}. FCFE = ${f.money(y.netIncome)} + ${f.money(y.da)} − ${f.money(y.capex)} − ${f.money(y.dNwc)} + ${f.money(y.netBorrowing)} = <b>${f.money(y.fcfe)}</b>.`,
        `Discount at the cost of equity ${f.pct(r.ke, 2)}: present values sum to ${f.money(r.sumPv)}; terminal value ${f.money(r.tv)} discounted to ${f.money(r.pvTV)}. Equity value <b>${f.money(r.equity)}</b>${fin(r.perShare) ? `, <b>${f.perShare(r.perShare)}</b> a share` : ''}.`,
      ];
    },
  },
  // ================================================================ SOTP
  sotp: {
    title: 'Sum of the parts', sources: ['mckinsey', 'damodaran-book', 'cfa'],
    steps: {
      what: L(['Value each division on its own, add them up, subtract head-office costs and debt.'], ['Each segment is valued with the multiple (or DCF) that suits its own industry; corporate costs are capitalised as a negative part; the total is enterprise value, bridged to equity as usual.'], ['The conglomerate discount is the gap between SOTP and the market value; it reflects complexity, capital misallocation and the cost of unwinding. SOTP is also the basis for break-up and spin-off analysis.']),
      when: L(['For companies with very different businesses under one roof.'], ['Conglomerates, holding companies, groups with a financial arm, and any company whose segments deserve different multiples because their growth, margins or risk differ.'], ['Required when segment disclosures exist and a single multiple would misprice the mix; used in activist and M&A analysis to show what the parts could fetch.']),
      data: L(['Profit (usually EBITDA) by division and a suitable multiple for each.'], ['Segment revenue, EBITDA or EBIT, capex and assets from the segment note; peer multiples for each segment’s industry; unallocated corporate costs; group debt, cash and minority interests.'], ['Inter-segment eliminations, shared assets, tax leakage on a break-up, and stakes in associates valued at market.']),
      where: L(['The segment note in the annual report lists each division’s sales and profit.'], ['IFRS 8 / ASC 280 segment reporting in the filings; peer multiples from comparable analyses per segment.'], ['Spin-off prospectuses and transaction multiples for similar divisions; sell-side SOTP sheets as a cross-check.']),
      inputs: L(['Each segment’s EBITDA and the multiple to apply; corporate costs; debt and cash.'], ['Segment metric (EBITDA, EBIT, revenue or a direct value) and multiple; corporate overhead (negative) and its multiple; the bridge.'], ['Tax on separation, dis-synergies, stranded costs and the time to execute if the SOTP is being used as a break-up value.']),
      formulas: L(['Value = Σ (segment profit × segment multiple) − corporate costs × multiple − net debt.'], ['EV = Σ metric<sub>i</sub> × multiple<sub>i</sub> + corporate; equity = EV − debt − claims + cash. Implied group multiple = EV ÷ group EBITDA.'], ['Discount = 1 − market EV ÷ SOTP EV. Per share after dilution.']),
      excel: L(['One row per segment: profit, multiple, value; a corporate row; totals; the bridge.'], ['Rows per segment with <code>=metric*multiple</code>, a corporate row with a negative metric, <code>=SUM</code>, bridge, per share, implied multiple.'], ['Add alternative multiples per segment (low/high) for a range, and a break-up version with tax and costs.']),
      interpret: L(['If the parts are worth more than the whole, the market is applying a discount for complexity or doubts about management.'], ['Compare the implied blended multiple with the market’s; explain the discount with capital allocation, transparency and the likelihood of a break-up.'], ['Weigh the discount against the costs of separation; SOTP is an upper bound unless a break-up is credible.']),
      mistakes: L(['Forgetting head-office costs; using the same multiple for every division; double-counting debt.'], ['Applying peer multiples to segment profits that are stated on a different basis (allocated costs); ignoring eliminations; valuing associates at book.'], ['Treating SOTP as achievable value without separation costs and taxes; cherry-picking generous multiples; ignoring minority interests at segment level.']),
    },
    worked(ctx, f) {
      const s = ctx.results?.sotp; if (!s?.ok) return [];
      return [...s.rows.map((r) => `${r.name}: ${r.how} = <b>${f.money(r.ev)}</b>.`), `Corporate costs: ${f.money(s.corporate.value)} × ${f.num(s.corporate.multiple, 1)} = ${f.money(s.corporate.ev)}. Sum of the parts (enterprise value) = <b>${f.money(s.ev)}</b>, an implied ${f.x(s.blended)} group EBITDA.`, `Equity = EV − debt ${f.money(s.debt)} − other claims + cash ${f.money(s.cash)} = <b>${f.money(s.equity)}</b>${fin(s.perShare) ? `, ${f.perShare(s.perShare)} a share` : ''}.`];
    },
  },
  // ================================================================ earnings-based
  earnings: {
    title: 'Earnings-based valuation', sources: ['inv-valuation', 'hbs-value', 'cfa'],
    steps: {
      what: L(['Turn a year’s profit into a value by dividing by a rate (or multiplying by a P/E).'], ['Capitalised earnings = normalised earnings ÷ capitalisation rate (k<sub>e</sub> − g). Earnings-power value = EBIT × (1 − t) ÷ WACC: the value of the current earnings with no growth. A target P/E applied to earnings is the market version.'], ['These are single-period shortcuts of the DCF. EPV isolates the value of growth: DCF − EPV = present value of growth opportunities, which is only positive if returns exceed the cost of capital.']),
      when: L(['For steady businesses whose profits are a fair guide to the future; common in valuing small private companies.'], ['Mature, stable companies; private-company and tax valuations; a floor for growth companies.'], ['Use EPV as a no-growth benchmark in every valuation; capitalised earnings when the growth is modest and steady.']),
      data: L(['A normal year’s profit and the rate to divide it by.'], ['Net income or EBIT normalised for one-offs, the cost of equity or WACC, a growth rate, a target P/E from peers.'], ['Several years of earnings to normalise through a cycle; the maintenance capex to adjust EBIT if depreciation misstates it.']),
      where: L(['The income statement.'], ['Filings for earnings, the WACC block for rates, comparables for the P/E.'], ['Cycle-average margins from history; owner’s earnings adjustments for private companies.']),
      inputs: L(['Earnings; the capitalisation rate (required return − growth); the P/E to apply.'], ['Normalised earnings (default: latest net income); cap rate = k<sub>e</sub> − g; tax rate for EPV; a target P/E.'], ['Growth consistent with reinvestment; EBIT adjusted for maintenance capex; a P/E adjusted for leverage.']),
      formulas: L(['Value = earnings ÷ rate; or value = earnings × P/E.'], ['Capitalised = E ÷ (k<sub>e</sub> − g); EPV<sub>EV</sub> = EBIT × (1 − t) ÷ WACC, then the bridge; P/E value = P/E × earnings.'], ['Equivalence: P/E = payout × (1 + g) ÷ (k<sub>e</sub> − g) for a stable firm, so a P/E embeds growth and payout assumptions.']),
      excel: L(['Three formulas in three cells.'], ['<code>=E/(ke-g)</code>, <code>=EBIT*(1-t)/WACC</code> with the bridge, <code>=PE*E</code>.'], ['Add normalisation rows and a comparison with the DCF to show the value of growth.']),
      interpret: L(['A quick floor: if the DCF is far above it, growth is doing the work.'], ['DCF − EPV is the value of growth; if large, test the returns that justify it.'], ['When EPV exceeds the DCF, the forecast assumes value-destroying growth: returns below the cost of capital.']),
      mistakes: L(['Using a bad year or an unusually good one as "normal"; forgetting that the P/E of peers already contains their growth.'], ['Capitalising net income at WACC or EBIT at k<sub>e</sub>; growth above the cap rate; ignoring one-offs.'], ['Treating EPV as a target rather than a floor; using accounting earnings without adjusting for maintenance investment.']),
    },
    worked(ctx, f) {
      const e = ctx.results?.earnings; if (!e?.ok) return [];
      return [`Capitalised earnings = ${f.money(e.earnings)} ÷ (${f.pct(e.ke, 2)} − g) = <b>${f.money(e.capitalised)}</b>.`, `Earnings-power value: EBIT × (1 − t) ÷ WACC = EV <b>${f.money(e.epvEv)}</b>; after the bridge, equity <b>${f.money(e.epv?.equity)}</b>${fin(e.perShare.epv) ? ` (${f.perShare(e.perShare.epv)} a share)` : ''}.`, fin(e.pe) ? `At a target P/E of ${f.x(e.pe)}: ${f.x(e.pe)} × ${f.money(e.earnings)} = <b>${f.money(e.peValue)}</b>.` : 'Enter a target P/E to apply the market version.'];
    },
  },
  // ================================================================ VC
  vc: {
    title: 'Venture-capital method', sources: ['damodaran-book', 'cfa'],
    steps: {
      what: L(['Guess what the company could be sold for in a few years, then shrink that back at the very high return an early investor demands.'], ['Exit value = exit-year metric × exit multiple. Post-money value today = exit value ÷ (1 + target return)<sup>n</sup>. The investor’s required ownership = investment ÷ post-money; pre-money = post-money − investment.'], ['The target return (30–60% a year) bundles the time value of money, the probability of failure and illiquidity. It is a pricing convention rather than a cost of capital; a probability-weighted DCF across outcomes is the more rigorous equivalent.']),
      when: L(['For start-ups that lose money now but could be big later.'], ['Seed to late-stage private rounds; companies with no earnings and little history; where the exit (sale or IPO) is the whole thesis.'], ['Pair it with a scenario DCF and with the revenue multiples of listed peers at exit; adjust for expected future dilution.']),
      data: L(['A forecast of sales or profit in the exit year, a multiple, the years to exit and the return the investor wants.'], ['Exit-year revenue or EBITDA, a peer exit multiple, years to exit, target IRR, the amount being invested and the expected retention after later rounds.'], ['Comparable exits and their multiples, failure rates by stage, option-pool and liquidation-preference terms.']),
      where: L(['The business plan for the forecast; recent sales of similar companies for the multiple.'], ['Management projections, peer multiples at exit, venture return benchmarks by stage.'], ['Transaction databases; term sheets for the structural terms.']),
      inputs: L(['Exit value; target return; years; investment.'], ['Exit metric and multiple; target return; years to exit; investment; retention (the share of today’s ownership that survives later dilution).'], ['Probability of success if a probability-weighted variant is used; preferred terms that change the common equity’s share of the exit.']),
      formulas: L(['Value today = exit value ÷ (1 + return)<sup>years</sup>.'], ['Post-money = EV<sub>exit</sub> ÷ (1 + r)<sup>n</sup>; ownership = I ÷ post-money; pre-money = post-money − I; required ownership today = ownership ÷ retention.'], ['With failure probability p and success value S: expected value = (1 − p) × S ÷ (1 + k)<sup>n</sup>, which maps the target return to a cost of capital k.']),
      excel: L(['Four cells: exit value, discount, pre- and post-money.'], ['<code>=metric*multiple</code>, <code>=exit/(1+r)^n</code>, <code>=post-I</code>, <code>=I/post/retention</code>.'], ['Add a sensitivity of ownership to the exit multiple and target return, and a cap table for dilution.']),
      interpret: L(['The low value reflects the risk of failure, not an insult to the company.'], ['Compare the required ownership with what the founders will accept; test the exit multiple against listed peers; the post-money is a price, not an intrinsic value.'], ['Back out the implied probability of success from the target return and judge it against stage failure rates.']),
      mistakes: L(['Treating the plan as certain; using today’s multiples for a sale years away; ignoring later rounds.'], ['Forgetting dilution; a target return too low for the stage; an exit multiple from a boom year.'], ['Ignoring liquidation preferences and option pools; double-discounting for risk in both the forecast and the rate.']),
    },
    worked(ctx, f) {
      const v = ctx.results?.vc; if (!v?.ok) return [];
      const s = ctx.project.vc || {};
      return [`Exit value in year ${s.exitYear} = ${f.money(s.exitMetric)} × ${f.x(s.exitMultiple)} = <b>${f.money(v.exitValue)}</b>.`, `Post-money value today = ${f.money(v.exitValue)} ÷ (1 + ${f.pct(s.targetReturn, 0)})<sup>${s.exitYear}</sup> = <b>${f.money(v.postMoney)}</b>; pre-money = post-money − investment ${f.money(s.investment)} = <b>${f.money(v.preMoney)}</b>.`, `Ownership required at exit = ${f.money(s.investment)} ÷ ${f.money(v.postMoney)} = <b>${f.pct(v.ownership)}</b>; allowing for later dilution (retention ${f.pct(v.retention, 0)}), the investor needs <b>${f.pct(v.ownershipToday)}</b> today.`];
    },
  },
};

